mapper.select:
SELECT a.attendance_id, a.schedule_id, a.student_id, a.status, a.record_time, a.remark,
       cs.course_date, cs.start_time, cs.end_time, cc.class_name
FROM attendance a
JOIN course_schedule cs ON a.schedule_id = cs.schedule_id
LEFT JOIN course_class cc ON cs.class_id = cc.class_id

    a.student_id = #{studentId}

        AND cs.course_date >= #{startDate}


        AND cs.course_date <= #{endDate}


        AND cs.class_id = #{classId}


ORDER BY cs.course_date DESC, cs.start_time ASC

SELECT a.* FROM attendance a
JOIN course_schedule cs ON a.schedule_id = cs.schedule_id


        AND cs.class_id = #{classId}


        AND cs.course_date = #{date}


        AND a.student_id = #{studentId}


ORDER BY cs.course_date DESC, a.record_time DESC
